FORCEINLINE_DEBUGGABLE FVec3 SupportCore(const FVec3& Direction, const FReal InMargin, FReal* OutSupportDelta, int32& OutVertexIndex) const
{
	FVec3 ChosenPt;
	FIntVector ChosenAxis;
	for (int Axis = 0; Axis < d; ++Axis)
	{
		if(Direction[Axis] < 0)
		{
			ChosenPt[Axis] = MMin[Axis] + InMargin;
			ChosenAxis[Axis] = 0;
		}
		else
		{
			ChosenPt[Axis] = MMax[Axis] - InMargin;
			ChosenAxis[Axis] = 1;
		}
	}

	OutVertexIndex = GetIndex(ChosenAxis);

	// Maximum distance between the Core+Margin position and the original outer vertex
	constexpr FReal RootThreeMinusOne = FReal(1.7320508075688772935274463415059 - 1.0);
	if (OutSupportDelta != nullptr)
	{
		*OutSupportDelta = RootThreeMinusOne * InMargin;
	}

	return ChosenPt;
}

FVec3 GetMarginAdjustedVertex(const int32 VertexIndex, const FReal InMargin, FReal* OutSupportDelta) const
{
	// @chaos(todo): moving the vertices this way based on margin is only valid for small margins. If the margin
	// is large enough to cause a face to reduce to zero size, vertices should be merged and the path is non-linear.
	// This can be fixed with some extra data in the convex structure, but for now we accept the fact that large 
	// margins on convexes with small faces can cause non-convex core shapes.

	if (InMargin == FReal(0))
	{
		return GetVertex(VertexIndex);
	}

	// Get any 3 planes that contribute to this vertex

FVec3 SupportCoreScaled(const FVec3& Direction, FReal InMargin, const FVec3& Scale, FReal* OutSupportDelta, int32& VertexIndex) const
{
	// Find the supporting vertex index
	const FVec3Type DirectionScaled = FVec3Type(Scale * Direction);	// does not need to be normalized
	const int32 SupportVertexIndex = GetSupportVertex(DirectionScaled);
	VertexIndex = SupportVertexIndex;
	// Adjust the vertex position based on margin
	if (SupportVertexIndex != INDEX_NONE)
	{
		if (InMargin == 0.0f)
		{
			return FVec3(GetVertex(VertexIndex)) * Scale;
		}
		else
		{
			// Note: Shapes wrapped in a non-uniform scale should not have their own margin and we assume that here
			// @chaos(todo): apply an upper limit to the margin to prevent a non-convex or null shape (also see comments in GetMarginAdjustedVertex)
			return FVec3(GetMarginAdjustedVertexScaled(SupportVertexIndex, InMargin, Scale, OutSupportDelta));
		}
	}
	return FVec3(0);

template <typename T, typename TGeometryA, typename TGeometryB>
bool GJKPenetrationWarmStartable(const TGeometryA& A, const TGeometryB& B, const TRigidTransform<T, 3>& BToATM, T& OutPenetration, TVec3<T>& OutClosestA, TVec3<T>& OutClosestB, TVec3<T>& OutNormalA, TVec3<T>& OutNormalB, int32& OutVertexA, int32& OutVertexB, TGJKSimplexData<T>& InOutSimplexData, T& OutMaxSupportDelta, const T Epsilon = T(1.e-3), const T EPAEpsilon = T(1.e-2))
{
	T SupportDeltaA = 0;
	T SupportDeltaB = 0;
	T MaxSupportDelta = 0;

	int32& VertexIndexA = OutVertexA;
	int32& VertexIndexB = OutVertexB;

	// Return the support vertex in A-local space for a vector V in A-local space
	auto SupportAFunc = [&A, &SupportDeltaA, &VertexIndexA](const TVec3<T>& V)
	{
		return A.SupportCore(V, A.GetMarginf(), &SupportDeltaA, VertexIndexA);
	};

	const TRotation<T, 3> AToBRotation = BToATM.GetRotation().Inverse();

	// Return the support point on B, in B-local space, for a vector V in A-local space
	auto SupportBFunc = [&B, &AToBRotation, &SupportDeltaB, &VertexIndexB](const TVec3<T>& V)
	{
		const TVec3<T> VInB = AToBRotation * V;
		return B.SupportCore(VInB, B.GetMarginf(), &SupportDeltaB, VertexIndexB);
	};

	// V and Simplex are in A-local space

const TVec3<T> NegV = -V;
const TVec3<T> SupportA = SupportAFunc(NegV);
const TVec3<T> SupportB = SupportBFunc(V);
const TVec3<T> SupportBInA = BToATM.TransformPositionNoScale(SupportB);
const TVec3<T> W = SupportA - SupportBInA;
MaxSupportDelta = FMath::Max(SupportDeltaA, SupportDeltaB);

// If we didn't move to at least ConvergedDistance or closer, assume we have reached a minimum
const T ConvergenceTolerance = 1.e-4f;
const T ConvergedDistance = (1.0f - ConvergenceTolerance) * Distance;
const T VW = TVec3<T>::DotProduct(V, W);

InOutSimplexData.As[SimplexIDs.NumVerts] = SupportA;
InOutSimplexData.Bs[SimplexIDs.NumVerts] = SupportB;
SimplexIDs[SimplexIDs.NumVerts] = SimplexIDs.NumVerts;
Simplex[SimplexIDs.NumVerts++] = W;

V = SimplexFindClosestToOrigin(Simplex, SimplexIDs, InOutSimplexData.Barycentric, InOutSimplexData.As, InOutSimplexData.Bs);
T NewDistance = V.Size();

// Are we overlapping or too close for GJK to get a good result?
bIsContact = (NewDistance < Epsilon);

	{
	case EEPAResult::MaxIterations:
		// Possibly a solution but with unknown error. Just return the last EPA state. 
		// Fall through...
	case EEPAResult::Ok:
		// EPA has a solution - return it now
		OutNormalA = MTD;
		OutNormalB = BToATM.InverseTransformVectorNoScale(MTD);
		OutPenetration = Penetration + ThicknessA + ThicknessB;
		OutClosestA = ClosestA + MTD * ThicknessA;
		OutClosestB = BToATM.InverseTransformPositionNoScale(ClosestBInA - MTD * ThicknessB);
		OutMaxSupportDelta = MaxSupportDelta;
		return true;
	case EEPAResult::BadInitialSimplex:
		// The origin is outside the simplex. Must be a touching contact and EPA setup will have calculated the normal
		// and penetration but we keep the position generated by GJK.
		Normal = MTD;
		Distance = -Penetration;
		//UE_LOGF(LogChaos, Warning, "EPA Touching Case");
		break;
	case EEPAResult::Degenerate:
		// We hit a degenerate simplex condition and could not reach a solution so use whatever near touching point GJK came up with.
		// The result from EPA under these circumstances is not usable.
		//UE_LOGF(LogChaos, Warning, "EPA Degenerate Case");
		break;
	}
}

// @todo(chaos): handle the case where EPA hits a degenerate triangle in the simplex.
// Currently we return a touching contact with the last position and normal from GJK. We could run SAT instead.

// Find the deepest penetration. This is used to determine the planes and points to use for the manifold
// MaxMarginDelta is an upper bound on the distance from the contact on the rounded core shape to the actual shape surface. 
FReal MaxMarginDelta = FReal(0);
int32 VertexIndexA = INDEX_NONE, VertexIndexB = INDEX_NONE;
FContactPoint GJKContactPoint = GJKContactPointMargin(Convex1, Convex2, Convex2ToConvex1Transform, Margin1, Margin2, Constraint.GetGJKWarmStartData(), MaxMarginDelta, VertexIndexA, VertexIndexB);
PHYSICS_CSV_CUSTOM_EXPENSIVE(PhysicsCounters, NumManifoldsGJKCalled, 1, ECsvCustomStatOp::Accumulate);

// We are seeing very rare cases where the VertexIndex is not set from an FConvex, even though the convex has vertices
// @todo(chaos): track down this problem - there is no path through GJKContactPointMargin (for FConvex) which does not set the VertexIndex
if (!CheckVertexIndex(Convex1, VertexIndexA) || !CheckVertexIndex(Convex2, VertexIndexB))
{
	return;
}

const bool bCanUpdateManifold = bChaos_Collision_EnableManifoldGJKReplace;
if (bCanUpdateManifold && Constraint.TryAddManifoldContact(GJKContactPoint))
{
	PHYSICS_CSV_CUSTOM_EXPENSIVE(PhysicsCounters, NumManifoldsMaintained, 1, ECsvCustomStatOp::Accumulate);
	return;
}

Constraint.ResetActiveManifoldContacts();

// GJK is using margins and rounded corner, so if we have a corner-to-corner contact it will under-report the actual distance by an amount that depends on how
// "pointy" the edge/corner is - this error is bounded by MaxMarginDelta.
const FReal GJKCullDistance = Constraint.GetCullDistance() + MaxMarginDelta;
if (GJKContactPoint.Phi > GJKCullDistance)
{
	PHYSICS_CSV_CUSTOM_EXPENSIVE(PhysicsCounters, NumManifoldsGJKCulled, 1, ECsvCustomStatOp::Accumulate);
